\maketitle

\begin{abstract}
We develop a rigorous theory of \emph{delayed transitions} in two-layer
rectified-linear networks and of the \emph{scaling laws} governing the length of
the delay. Structurally, for a two-layer ReLU network of hidden width $m$ with
negative output bias, non-positive hidden biases and non-negative output weights,
probed along a ray $t \mapsto tp$, the worst-case classification margin over a
finite two-class test set has a sharp and unique threshold $\tau \ge 0$; the
threshold is sandwiched between $|c|/S$, with $S = \sum_j a_j g_j$ the total
signal, and a single-unit bound, and it equals $|c|/S$ exactly when the hidden
biases vanish. This yields an exact $1/m$ width law, almost surely
$m\,\tau_m \to |c|/\Ex[Y]$ for i.i.d.\ hidden units with integrable signal $Y$ of
positive mean. Non-negativity of the output weights is necessary: it makes the
ramped output convex, so the failure set is an interval and relapse is impossible,
whereas an explicit width-$3k$ network with signed output weights has a failure set
with at least $k+1$ connected components. Dynamically, weight-decayed gradient flow
on the ridge loss $\tfrac{\lambda}{2}w^2 - sw$ produces the exact crossing time
$\tau(\lambda) = \lambda^{-1}\log\frac{s/\lambda-w_0}{s/\lambda-\theta}$, and the
threshold is crossed at all if and only if $\lambda < \lambda_c = s/\theta$, i.e.\
iff the bifurcation parameter $\mu(\lambda) = s/\lambda - \theta$ is positive.
Asymptotically---the main contribution---we determine the leading constants of both
delay laws: $\tau(\lambda) \sim \lambda_c^{-1}\log(1/\mu(\lambda))$ as
$\lambda \uparrow \lambda_c$, and $T_{\mathrm{pass}}(\mu,A) \sim \pi\,|\mu|^{-1/2}$
as $\mu \uparrow 0$ for the saddle-node normal form $\dot x = \mu - x^2$, the second
constant being exactly $\pi$ and independent of the observation level $A$. The ratio
of the logarithmic to the inverse-square-root delay tends to zero at criticality, so
the bottleneck law always dominates near the bifurcation.
\end{abstract}

\medskip
\noindent\textbf{Keywords:} grokking, delayed generalization, ReLU networks,
saddle-node bifurcation, weight decay, scaling laws, tropical geometry, Riccati
bottleneck.

\section{Introduction}

\emph{Grokking} denotes the empirical observation that a neural network trained past
the point of perfect training accuracy may remain at chance-level test accuracy for
a very long time and then, over a comparatively short window, transition to
near-perfect generalization. Two features call for explanation: the \emph{sharpness}
of the transition, which empirically is not repeated, and the \emph{delay}, which
can exceed the memorization time by orders of magnitude and depends strongly on
weight decay.

This paper isolates mechanisms responsible for each feature in models simple enough
to admit complete proofs, and extracts quantitative scaling laws with exact
constants, so that the mechanisms become distinguishable by measurement.

\paragraph{Contributions.}
\begin{itemize}
\item Sharp thresholds survive worst-case aggregation (\S\ref{sec:sharp}).
\item A closed-form delay: the sandwich
$|c|/S \le \tau \le (|c|/a_{j_0}-b_{j_0})/g_{j_0}$ and the exact identity
$\tau = |c|/S$ for zero hidden bias (\S\ref{sec:delay}).
\item Width laws, deterministic and almost sure (\S\ref{sec:width}).
\item Tropical rigidity and its failure: convexity forbids relapse; signed output
weights permit linearly many relapses (\S\ref{sec:tropical}).
\item A derived delay and a connection theorem relating weight decay to the
unfolding parameter of a saddle node (\S\ref{sec:training}).
\item Local bifurcation theory: nondegeneracy, exchange of stability, cubic reduced
loss, robustness (\S\ref{sec:saddle}).
\item Sharp constants $1/\lambda_c$ and $\pi$ for the two delay laws, and the proof
that the bottleneck dominates (\S\ref{sec:bottleneck}--\S\ref{sec:sharpconst}).
\item Train/test separation with an exact grokking window and unbounded grokking
ratio (\S\ref{sec:sep}).
\end{itemize}

Throughout, $\ReLU(u) = \max(u,0)$.

\section{Setting}

\begin{definition}[Two-layer ReLU network]
For hidden width $m$ and input dimension $d$, given hidden weights $W \in \R^{m\times d}$
with rows $W_j$, hidden biases $b \in \R^m$, output weights $a \in \R^m$ and output
bias $c \in \R$, set
\[
N(x) \;=\; c + \sum_{j=1}^m a_j\,\ReLU\bigl(\langle W_j, x\rangle + b_j\bigr),
\qquad x \in \R^d .
\]
\end{definition}

\begin{definition}[Signal and ramp]
For a direction $p \in \R^d$ the \emph{signal} of unit $j$ is
$g_j(p) = \langle W_j, p\rangle$, and the \emph{ramped output} is
\[
R_p(t) \;=\; N(tp) \;=\; c + \sum_{j=1}^m a_j \ReLU\bigl(t\,g_j(p) + b_j\bigr).
\]
\end{definition}

\begin{definition}[Signed score and margin]
Given labelled test points $p_1,\dots,p_n$ with labels $y_k \in \{\pm1\}$, put
$s_k(t) = y_k R_{p_k}(t)$ and $M(t) = \min_{1\le k\le n} s_k(t)$.
\end{definition}

\begin{definition}[Sharp threshold]
$\tau$ is a \emph{sharp threshold} of $f$ if $f(t)\le 0$ for all $t \le \tau$ and
$f(t) > 0$ for all $t > \tau$.
\end{definition}

\section{Sharp thresholds and worst-case aggregation}\label{sec:sharp}

\begin{theorem}[Existence]\label{thm:sharp}
Let $f:\R\to\R$ be non-decreasing and continuous with $f(0)<0$ and $f(T)>0$ for some
$T$. Then $f$ has a sharp threshold $\tau \ge 0$.
\end{theorem}

\begin{proof}[Proof sketch]
Let $F=\{t: f(t)\le0\}$. By monotonicity $F$ is a down-set containing $0$ and
bounded above by $T$; put $\tau=\sup F \ge 0$. For $t<\tau$ pick $u\in F$, $t<u$;
then $f(t)\le f(u)\le0$, and continuity gives $f(\tau)\le0$. For $t>\tau$, $t\notin F$,
so $f(t)>0$.
\end{proof}

\begin{proposition}[Uniqueness]
If $\tau<\tau'$ are both sharp thresholds of $f$, then $f(\tau')>0$ and
$f(\tau')\le 0$, a contradiction. Hence the sharp threshold is unique.
\end{proposition}

\begin{theorem}[Margins inherit sharp thresholds]\label{thm:margin}
Let $g_1,\dots,g_n$ be non-decreasing, continuous, each eventually positive, with
$g_{k_0}(0)<0$ for some $k_0$. Then $M=\min_k g_k$ has a sharp threshold $\tau \ge 0$.
\end{theorem}

\begin{proof}[Proof sketch]
A finite minimum of monotone (resp.\ continuous) functions is monotone (resp.\
continuous). $M(0)\le g_{k_0}(0)<0$. If $g_k(T_k)>0$ and $T=\max_k T_k$ then
$g_k(T)\ge g_k(T_k)>0$ for all $k$, so $M(T)>0$. Apply Theorem~\ref{thm:sharp}.
\end{proof}

\begin{theorem}[Delayed positivity of the network margin]\label{thm:netmargin}
Let $c<0$, $a_j\ge0$, $b_j\le0$ for all $j$, and let $(p_k,y_k)_{k\le n}$, $n\ge1$, be
a two-class test set such that: negative-class points are silent
($y_k=-1 \Rightarrow g_j(p_k)\le0$ for all $j$); positive-class points are aligned
($y_k=+1 \Rightarrow g_j(p_k)\ge0$ for all $j$) and active
($y_k=+1 \Rightarrow \exists j_0,\ a_{j_0}>0,\ g_{j_0}(p_k)>0$); and at least one
$y_k=+1$. Then there is a unique $\tau\ge0$ with $M(t)\le0$ for $t\le\tau$ and
$M(t)>0$ for $t>\tau$.
\end{theorem}

\begin{proof}[Proof sketch]
For $y_k=+1$, non-negative signals and output weights make $R_{p_k}$ non-decreasing;
for $y_k=-1$ all signals are non-positive so $R_{p_k}$ is non-increasing and the
score $-R_{p_k}$ is non-decreasing. All scores are continuous. At $t=0$ a
positive-class point has every unit silent since $b_j\le0$, so its score is $c<0$.
Every score is eventually positive: for $y_k=-1$ the score equals $-c>0$ for $t\ge0$;
for $y_k=+1$ the active unit drives the output above $0$ once
$t>(|c|/a_{j_0}-b_{j_0})/g_{j_0}(p_k)$. Apply Theorem~\ref{thm:margin}.
\end{proof}

\section{The delay: bounds and an exact formula}\label{sec:delay}

Fix $p$, write $g_j=g_j(p)$ and $S=\sum_j a_j g_j$.

\begin{lemma}[Linear domination]\label{lem:lin}
If $a_j\ge0$, $b_j\le0$, $g_j\ge0$ for all $j$, then $R_p(t)\le c+tS$ for $t\ge0$.
\end{lemma}

\begin{proof}
$\ReLU(tg_j+b_j)\le tg_j$ since $tg_j\ge0$ and $tg_j \ge tg_j+b_j$; multiply by
$a_j\ge0$ and sum.
\end{proof}

\begin{theorem}[Lower bound]\label{thm:lb}
Under the hypotheses of Lemma~\ref{lem:lin} with $c<0$ and $S>0$: if $R_p(t)>0$ for
all $t>\tau$, then $\tau \ge |c|/S$.
\end{theorem}

\begin{proof}[Proof sketch]
If $\tau<|c|/S$, take $\tau<t<|c|/S$. Then $R_p(t)>0$, but
$R_p(t)\le c+tS<c+|c|=0$.
\end{proof}

\begin{theorem}[Upper bound]\label{thm:ub}
Let $a_j\ge0$ and suppose $a_{j_0}>0$, $g_{j_0}>0$. If $R_p(t)\le0$ for all
$t\le\tau$, then $\tau \le (|c|/a_{j_0}-b_{j_0})/g_{j_0}$.
\end{theorem}

\begin{proof}[Proof sketch]
Let $T$ be the right-hand side, so $Tg_{j_0}+b_{j_0}=|c|/a_{j_0}$. If $\tau>T$,
choose $T'\in(T,\tau]$; then $a_{j_0}\ReLU(T'g_{j_0}+b_{j_0})>|c|$ and every other
summand is non-negative, so $R_p(T')>0$, contradicting $R_p(T')\le0$.
\end{proof}

\begin{corollary}[Delay sandwich]\label{cor:sandwich}
Under both sets of hypotheses, any sharp threshold satisfies
\[
\frac{|c|}{\sum_j a_j g_j} \;\le\; \tau \;\le\; \frac{|c|/a_{j_0}-b_{j_0}}{g_{j_0}} .
\]
\end{corollary}

\begin{theorem}[Exact delay for vanishing hidden biases]\label{thm:exact}
If $b_j=0$, $g_j\ge0$ for all $j$, $c<0$ and $S>0$, then the sharp threshold of
$R_p$ is exactly $\tau = |c|/S$.
\end{theorem}

\begin{proof}[Proof sketch]
For $t\ge0$, $\ReLU(tg_j)=tg_j$, so $R_p(t)=c+tS$; for $t\le0$ all units are silent
and $R_p(t)=c<0$. The affine formula gives $R_p(t)\le0$ iff $t\le|c|/S$.
\end{proof}

\begin{remark}
$\tau=|c|/S$ reads \emph{delay $=$ prior resistance $/$ evidence rate}: doubling the
output bias doubles the wait, doubling the total signal halves it.
\end{remark}

\section{Width laws}\label{sec:width}

\begin{definition}[Symmetric network]
Fix $A,g>0$, $c<0$, $d=1$, $p=1$, and $m$ identical units with weight $g$, bias $0$
and output weight $A$. Then $S=mAg$ and Theorem~\ref{thm:exact} gives
$\tau(m)=|c|/(mAg)$.
\end{definition}

\begin{theorem}[Exact $1/m$ width law]
For all $m\ge1$, $m\,\tau(m)=|c|/(Ag)$, independent of $m$; hence $\tau(m)\to0$.
\end{theorem}

Let now the units be heterogeneous with per-unit signals $u_j=a_jg_j\ge0$,
$S_m=\sum_{j<m}u_j$ and $\tau_m=|c|/S_m$.

\begin{theorem}[Ces\`aro width law]\label{thm:cesaro}
If $m^{-1}S_m \to L>0$, then $m\,\tau_m \to |c|/L$.
\end{theorem}

\begin{proof}[Proof sketch]
$m\,\tau_m = |c|/(m^{-1}S_m)$ whenever $S_m\neq0$; eventually $m^{-1}S_m>L/2>0$,
and division is continuous away from zero.
\end{proof}

\begin{theorem}[Almost-sure width law]\label{thm:slln}
Let $(Y_j)_{j\ge0}$ be pairwise independent, identically distributed, integrable,
with $\Ex[Y_0]>0$, playing the role of the per-unit signals. Then almost surely
$m\,\tau_m \to |c|/\Ex[Y_0]$.
\end{theorem}

\begin{proof}[Proof sketch]
The strong law of large numbers gives $m^{-1}\sum_{j<m}Y_j\to\Ex[Y_0]$ almost surely;
apply Theorem~\ref{thm:cesaro} pathwise on that full-measure event.
\end{proof}

\section{Tropical rigidity, and how to break it}\label{sec:tropical}

\begin{theorem}[Convexity of the ramped output]\label{thm:convex}
If $a_j\ge0$ for all $j$, then $t\mapsto R_p(t)$ is convex on $\R$.
\end{theorem}

\begin{proof}[Proof sketch]
Each $t\mapsto \ReLU(tg_j+b_j)$ is a maximum of two affine functions, hence convex;
a non-negative combination of convex functions plus a constant is convex.
\end{proof}

\begin{corollary}[The failure set is an interval]\label{cor:interval}
If $a_j\ge0$, then $\{t : R_p(t)\le0\}$ is convex; in particular the network cannot
fail, succeed, and fail again along the ramp.
\end{corollary}

\begin{theorem}[A network that groks twice]\label{thm:hat}
Let
\[
H(t) = -\tfrac12 + \ReLU(t) - 2\,\ReLU(t-1) + \ReLU(t-2),
\]
a width-$3$, one-dimensional two-layer ReLU network with hidden weights $(1,1,1)$,
hidden biases $(0,-1,-2)$, output weights $(1,-2,1)$ and output bias $-1/2$. Then
\[
\{t : H(t)\le 0\} \;=\; (-\infty,\tfrac12] \cup [\tfrac32,\infty),
\]
which is not convex; equivalently $H>0$ exactly on $(\tfrac12,\tfrac32)$.
\end{theorem}

\begin{proof}[Proof sketch]
The kinks at $0,1,2$ split $\R$ into four affine pieces: $H\equiv-\tfrac12$ on
$(-\infty,0]$, $H(t)=-\tfrac12+t$ on $[0,1]$, $H(t)=-\tfrac12+(2-t)$ on $[1,2]$, and
$H\equiv-\tfrac12$ on $[2,\infty)$: a tent crossing $0$ upward at $\tfrac12$ and
downward at $\tfrac32$.
\end{proof}

\begin{theorem}[Linearly many relapses]\label{thm:comb}
For $k\ge1$ let
$\beta_i(t)=\ReLU(t-2i)-2\ReLU(t-2i-1)+\ReLU(t-2i-2)$ be the tent supported on
$[2i,2i+2]$ with peak $1$ at $2i+1$, and set
$C_k(t) = -\tfrac12 + \sum_{i=0}^{k-1}\beta_i(t)$. Then $C_k$ is a two-layer ReLU
network of hidden width $3k$ with signed output weights, $C_k(2i)=-\tfrac12$ for all
integers $i$, and $C_k(2i+1)=+\tfrac12$ for $0\le i<k$. Consequently
$\{t : C_k(t)\le0\}$ has at least $k+1$ connected components and, for $k\ge1$, is not
convex.
\end{theorem}

\begin{proof}[Proof sketch]
Adjacent tents meet only at endpoints where both vanish, so all bumps vanish at even
integers and exactly one attains its peak at $2i+1$, $i<k$. Distinct even integers
$2i<2j\le 2k$ are separated inside the failure set by the point $2i+1$, where
$C_k>0$; hence they lie in distinct components, giving $k+1$ of them. Non-convexity
follows since $0,2k$ are failures but $1$ is not.
\end{proof}

\section{Deriving the delay from training dynamics}\label{sec:training}

\begin{definition}[Ridge loss and gradient flow]
For $\lambda>0$, $s>0$ let $L_\lambda(w) = \tfrac{\lambda}{2}w^2 - sw$, so
$L_\lambda'(w)=\lambda w - s$. The gradient flow $\dot w = s - \lambda w$ with
$w(0)=w_0$ has the explicit solution
\[
w_\lambda(t) = \frac{s}{\lambda} + \Bigl(w_0 - \frac{s}{\lambda}\Bigr)e^{-\lambda t}.
\]
\end{definition}

\begin{proposition}
$w_\lambda(0)=w_0$ and $\dot w_\lambda = -L_\lambda'(w_\lambda)$. If
$w_0 < s/\lambda$ then $w_\lambda$ is strictly increasing and
$w_\lambda(t) < s/\lambda$ for all $t$.
\end{proposition}

\begin{definition}[Crossing time]
For $w_0 < \theta < s/\lambda$,
\[
\tau(\lambda) = \frac{1}{\lambda}\log\!\left(\frac{s/\lambda - w_0}{s/\lambda-\theta}\right).
\]
\end{definition}

\begin{theorem}[Exact crossing law]\label{thm:cross}
For $\lambda>0$ and $w_0<\theta<s/\lambda$ and every $t\in\R$,
$w_\lambda(t)>\theta \iff t>\tau(\lambda)$.
\end{theorem}

\begin{proof}[Proof sketch]
$w_\lambda(t)>\theta$ is equivalent to
$e^{-\lambda t} < \frac{s/\lambda-\theta}{s/\lambda-w_0}$, both sides positive;
taking logarithms and using
$\log\frac{s/\lambda-\theta}{s/\lambda-w_0}=-\log\frac{s/\lambda-w_0}{s/\lambda-\theta}$
gives $-\lambda t < -\lambda\tau(\lambda)$.
\end{proof}

\begin{corollary}[Trained delayed transition]
$\ReLU(w_\lambda(t)-\theta)=0$ for $t\le\tau(\lambda)$ and
$\ReLU(w_\lambda(t)-\theta)>0$ for $t>\tau(\lambda)$: the delay is now produced by
optimization rather than assumed.
\end{corollary}

\begin{definition}
$\mu(\lambda) = \dfrac{s}{\lambda}-\theta$ and $\lambda_c = \dfrac{s}{\theta}$.
For $\lambda,\theta>0$, $\mu(\lambda)>0 \iff \lambda<\lambda_c$.
\end{definition}

\begin{theorem}[Connection theorem: regularization $\mapsto$ normal form]\label{thm:connection}
For $\lambda,\theta>0$ and $w_0<\theta$,
\[
\bigl(\exists\,t\ge0 :\ w_\lambda(t) > \theta\bigr)
\iff \lambda<\lambda_c \iff \mu(\lambda)>0 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
($\Leftarrow$) If $\mu>0$ then $\theta<s/\lambda$ and Theorem~\ref{thm:cross}
applies at $t>\max(0,\tau(\lambda))$. ($\Rightarrow$) If $s/\lambda\le\theta$, then
since $e^{-\lambda t}\in(0,1]$ for $t\ge0$ and $w_0<\theta$ we get
$w_\lambda(t)\le\theta$ for all $t\ge0$.
\end{proof}

\begin{theorem}[Divergence at criticality]\label{thm:diverge}
For $\theta>0$, $w_0<\theta$, $s>0$,
\[
\frac{1}{\lambda}\log\frac{\theta-w_0}{\mu(\lambda)} \;\le\; \tau(\lambda),
\]
and $\tau(\lambda)\to+\infty$ as $\lambda\uparrow\lambda_c$; in particular for every
$T$ there is a subcritical $\lambda$ with $\tau(\lambda)>T$.
\end{theorem}

\begin{proof}[Proof sketch]
The bound follows from
$\frac{\theta-w_0}{\mu}\le\frac{s/\lambda-w_0}{s/\lambda-\theta}$ and monotonicity of
$\log$. Given $T$, choose $\mu$ so small that $\log\frac{\theta-w_0}{\mu}>\lambda_cT$
and set $\lambda=s/(\theta+\mu)<\lambda_c$; since $1/\lambda \ge 1/\lambda_c$ the
bound exceeds $T$.
\end{proof}

\begin{theorem}[Discrete gradient descent]
Let $w_{k+1}=w_k-\eta(\lambda w_k - s)$ with $\eta>0$ and $\eta\lambda<1$. Then
$w_k = \frac{s}{\lambda}+\bigl(w_0-\frac{s}{\lambda}\bigr)(1-\eta\lambda)^k$, and if
$w_k>\theta$ for some $k$ with $w_0<\theta<s/\lambda$, then
\[
k \;>\; \frac{\log\bigl((s/\lambda-\theta)/(s/\lambda-w_0)\bigr)}{\log(1-\eta\lambda)} .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Induction gives the closed form; $w_k>\theta$ yields
$(1-\eta\lambda)^k<\frac{s/\lambda-\theta}{s/\lambda-w_0}$, and dividing by
$\log(1-\eta\lambda)<0$ reverses the inequality.
\end{proof}

\section{Local saddle-node theory}\label{sec:saddle}

\begin{definition}
$f_\mu(x) = \mu - x^2$, with flow $\dot x = f_\mu(x)$.
\end{definition}

\begin{theorem}[Nondegeneracy]
At $(\mu,x)=(0,0)$: $f_0(0)=0$, $\partial_x f_0(0)=0$, $\partial_\mu f_\mu(x)=1\neq0$,
$\partial_x^2 f_\mu(x)=-2\neq0$ --- the classical saddle-node conditions.
\end{theorem}

\begin{theorem}[Branches and exchange of stability]
For $\mu>0$, $f_\mu(x)=0$ iff $x=\pm\sqrt\mu$, and
$\partial_xf_\mu(\sqrt\mu)=-2\sqrt\mu<0$ while
$\partial_xf_\mu(-\sqrt\mu)=+2\sqrt\mu>0$. At $\mu=0$ the unique equilibrium is
linearly degenerate; for $\mu<0$ there is no equilibrium.
\end{theorem}

\begin{theorem}[Nonlinear attraction and repulsion]
Let $\mu>0$ and let $x(\cdot)$ solve $\dot x=\mu-x^2$. If $x(t)>-\sqrt\mu$ and
$x(t)\neq\sqrt\mu$, then $\frac{d}{dt}(x(t)-\sqrt\mu)^2<0$. If $x(t)<\sqrt\mu$ and
$x(t)\neq-\sqrt\mu$, then $\frac{d}{dt}(x(t)+\sqrt\mu)^2>0$.
\end{theorem}

\begin{proof}[Proof sketch]
$\frac{d}{dt}(x-\sqrt\mu)^2 = 2(x-\sqrt\mu)(\mu-x^2) = -2(x-\sqrt\mu)^2(x+\sqrt\mu)$,
using $(\sqrt\mu)^2=\mu$; the mirrored identity gives the second claim.
\end{proof}

\begin{theorem}[Cubic reduced loss]
Let $V_\mu(x)=\frac{x^3}{3}-\mu x$. Then $V_\mu'(x)=x^2-\mu=-f_\mu(x)$, so the normal
form is the negative gradient flow of $V_\mu$ and critical points are exactly
equilibria. For $\mu>0$, $\sqrt\mu$ is a strict local minimum and $-\sqrt\mu$ a strict
local maximum; for $\mu<0$ there is no critical point.
\end{theorem}

\begin{proof}[Proof sketch]
The exact factorization
$V_\mu(x)-V_\mu(\sqrt\mu)=\tfrac13(x-\sqrt\mu)^2(x+2\sqrt\mu)$ gives the local
minimum, and its mirror gives the local maximum. For $\mu<0$, $x^2-\mu\ge-\mu>0$.
\end{proof}

\begin{theorem}[Robustness of the bifurcation diagram]\label{thm:robust}
Let $g$ be continuous with $|g(x)-(\mu-x^2)|\le\varepsilon$ for all $x$.
\begin{enumerate}
\item If $0<\varepsilon<\mu$, then $g$ has at least two zeros, one in $(-b,0)$ and one
in $(0,b)$, where $b=\sqrt{\mu+2\varepsilon}$.
\item Every zero $x$ of $g$ satisfies $|x^2-\mu|\le\varepsilon$.
\item If $\mu<-\varepsilon$, then $g$ has no zero.
\end{enumerate}
\end{theorem}

\begin{proof}[Proof sketch]
(1) $g(0)\ge\mu-\varepsilon>0$ while $g(\pm b)\le\mu-b^2+\varepsilon=-\varepsilon<0$;
apply the intermediate value theorem on $(0,b)$ and $(-b,0)$. (2) Immediate from
$g(x)=0$ and the uniform bound. (3) $g(x)\le\mu+\varepsilon<0$.
\end{proof}

\section{The bottleneck below the saddle node}\label{sec:bottleneck}

Write $\mu=-k^2$ with $k=\sqrt{-\mu}>0$.

\begin{theorem}[Exact Riccati solution]
$x_k(t)=-k\tan(kt)$ satisfies $\dot x_k = -k^2 - x_k^2$ wherever $\cos(kt)\neq0$;
i.e.\ it solves $\dot x=\mu-x^2$ with $\mu=-k^2$.
\end{theorem}

\begin{proof}
$\frac{d}{dt}\bigl(-k\tan(kt)\bigr) = -k^2\sec^2(kt) = -k^2\bigl(1+\tan^2(kt)\bigr)
= -k^2 - x_k(t)^2$.
\end{proof}

\begin{definition}[Passage time]
For an observation level $A>0$, $\;T(k,A) = \dfrac{2\arctan(A/k)}{k}$.
\end{definition}

\begin{proposition}[Endpoints]
$x_k\bigl(-\arctan(A/k)/k\bigr)=A$ and $x_k\bigl(\arctan(A/k)/k\bigr)=-A$, so
$T(k,A)$ is exactly the time needed to descend from $+A$ to $-A$.
\end{proposition}

\begin{theorem}[Inverse-square-root lower bound]\label{thm:lbpass}
If $0<k\le A$ then $T(k,A)\ge \dfrac{\pi}{2k}$.
\end{theorem}

\begin{proof}
$A/k\ge1$ gives $\arctan(A/k)\ge\pi/4$, so $T\ge \pi/(2k)$.
\end{proof}

\begin{corollary}
For $\mu<0$ and $A\ge\sqrt{-\mu}$,
$T(\sqrt{-\mu},A)\ge\frac{\pi}{2}|\mu|^{-1/2}$: the passage time diverges with
exponent $1/2$ as $\mu\uparrow0$.
\end{corollary}

\section{Sharp constants and the exponent dichotomy}\label{sec:sharpconst}

\begin{theorem}[Sharp constant of the relaxation delay]\label{thm:sharplog}
Let $s>0$, $\theta>0$, $w_0<\theta$. Then
\[
\lim_{\lambda\uparrow\lambda_c}\ \frac{\tau(\lambda)}{\log\bigl(1/\mu(\lambda)\bigr)}
\;=\; \frac{\theta}{s} \;=\; \frac{1}{\lambda_c},
\qquad\text{i.e.}\qquad
\tau(\lambda) \sim \frac{1}{\lambda_c}\log\frac{1}{\mu(\lambda)} .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Work on $(\lambda_-,\lambda_c)$ with $\lambda_-=s/(2\theta-w_0)<\lambda_c$, where
$\theta<s/\lambda<2\theta-w_0$ and hence $\mu(\lambda)\in(0,\theta-w_0)$, so both
logarithms below are defined. Split
\[
\tau(\lambda) = \frac{1}{\lambda}\Bigl[\log\bigl(s/\lambda-w_0\bigr)
+\log\bigl(1/\mu(\lambda)\bigr)\Bigr].
\]
As $\lambda\uparrow\lambda_c$: $s/\lambda\to\theta$, so $\mu(\lambda)\to0^+$ and
$\log(1/\mu(\lambda))\to+\infty$, whereas $\log(s/\lambda-w_0)\to\log(\theta-w_0)$ is
finite. Therefore
\[
\frac{\tau(\lambda)}{\log(1/\mu(\lambda))}
= \frac{1}{\lambda}\left[\frac{\log(s/\lambda-w_0)}{\log(1/\mu(\lambda))}+1\right]
\longrightarrow \frac{1}{\lambda_c}\,[0+1] = \frac{\theta}{s}. \qedhere
\]
\end{proof}

\begin{theorem}[Sharp constant of the passage time]\label{thm:sharppi}
For every fixed $A>0$, $\;\lim_{k\downarrow0} k\,T(k,A) = \pi$.
\end{theorem}

\begin{proof}
$k\,T(k,A)=2\arctan(A/k)$ identically for $k>0$; as $k\downarrow0$, $A/k\to+\infty$
and $\arctan\to\pi/2$.
\end{proof}

\begin{theorem}[Sharp inverse-square-root law]\label{thm:sharpsqrt}
For every $A>0$,
\[
\lim_{\mu\uparrow0}\ \sqrt{-\mu}\;T\bigl(\sqrt{-\mu},A\bigr) = \pi,
\qquad\text{i.e.}\qquad T\bigl(\sqrt{-\mu},A\bigr)\sim \pi\,|\mu|^{-1/2}.
\]
\end{theorem}

\begin{proof}
$\mu\mapsto\sqrt{-\mu}$ maps a left neighbourhood of $0$ into a right neighbourhood of
$0$ and tends to $0$ there; compose with Theorem~\ref{thm:sharppi}.
\end{proof}

\begin{remark}
The exponent is $-1/2$ rather than logarithmic, and the constant $\pi$ does
\emph{not} depend on $A$: asymptotically all of the time is spent in an arbitrarily
small neighbourhood of the ghost equilibrium, so the answer forgets the boundary
conditions. This $A$-independence is the mathematical signature of a bottleneck.
\end{remark}

\begin{theorem}[The relaxation delay is asymptotically negligible]\label{thm:ratio}
For every $K\in\R$ and $D>0$,
\[
\lim_{\mu\downarrow0}\ \frac{K\log(D/\mu)}{\pi/(2\sqrt\mu)} = 0 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
The ratio equals $\frac{2K}{\pi}\bigl[\sqrt\mu\log D + \sqrt\mu\log(1/\mu)\bigr]$; the
first term tends to $0$, and $\sqrt\mu\log(1/\mu)\to0$ since $x^r\log x\to0$ for
$r=1/2$.
\end{proof}

\begin{theorem}[Quantitative dominance]\label{thm:dominance}
For every $K\in\R$, $D>0$, $A>0$ there is $\delta>0$ such that
$K\log(D/\mu) < T(\sqrt\mu, A)$ for all $\mu\in(0,\delta)$.
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:ratio} pick $\delta_1$ with $K\log(D/\mu)<\pi/(2\sqrt\mu)$ on
$(0,\delta_1)$, and $\delta_2$ with $\sqrt\mu\le A$ on $(0,\delta_2)$; then
Theorem~\ref{thm:lbpass} gives $\pi/(2\sqrt\mu)\le T(\sqrt\mu,A)$. Take
$\delta=\min(\delta_1,\delta_2)$.
\end{proof}

